function getLuminanceTranslation(key, lang) {
    if (luminanceTranslations[lang] && luminanceTranslations[lang][key]) {
        return luminanceTranslations[lang][key];
    }
    if (luminanceTranslations.en && luminanceTranslations.en[key]) {
        return luminanceTranslations.en[key];
    }
    return null;
}

function applyLuminanceTranslations(lang) {
    
    let count = 0;
    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');
        if (key && key.startsWith('review.luminance.')) {
            const translation = getLuminanceTranslation(key, lang);
            if (translation) {
                element.textContent = translation;
                count++;
            }
        }
    });
    
}

document.addEventListener('languageChanged', (e) => {
    const lang = e.detail.language;
    setTimeout(() => applyLuminanceTranslations(lang), 200);
});

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
        applyLuminanceTranslations(currentLang);
    });
} else {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyLuminanceTranslations(currentLang);
}


